            return other instanceof Key key && Objects.equals(sheetId, key.sheetId) && Objects.equals(tag, key.tag);
        }

        @Override
        public int hashCode() {
            return Objects.hash(sheetId, tag);
        }
    }

    @Id
    @Column(name = "sheet_id", nullable = false)
